const scene=new THREE.Scene();scene.background=new THREE.Color(0x111817);scene.fog=new THREE.FogExp2(0x111817,.026);const camera=new THREE.PerspectiveCamera(68,innerWidth/innerHeight,.1,180);
scene.add(new THREE.HemisphereLight(0xa6b6a3,0x151916,1.15));const moon=new THREE.DirectionalLight(0xb7c2ae,2.1);moon.position.set(-16,28,12);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-38;moon.shadow.camera.right=38;moon.shadow.camera.top=38;moon.shadow.camera.bottom=-38;scene.add(moon);
const mats={ground:new THREE.MeshStandardMaterial({color:0x252a22,roughness:1}),dirt:new THREE.MeshStandardMaterial({color:0x403a2c,roughness:1}),bark:new THREE.MeshStandardMaterial({color:0x26221b,roughness:1}),leaf:new THREE.MeshStandardMaterial({color:0x202a22,roughness:1}),leaf2:new THREE.MeshStandardMaterial({color:0x30372a,roughness:1}),stone:new THREE.MeshStandardMaterial({color:0x343936,roughness:.9}),metal:new THREE.MeshStandardMaterial({color:0x555750,metalness:.65,roughness:.45}),rust:new THREE.MeshStandardMaterial({color:0x783c2b,metalness:.4,roughness:.75}),glow:new THREE.MeshStandardMaterial({color:0xff9a52,emissive:0xff521c,emissiveIntensity:2}),blue:new THREE.MeshStandardMaterial({color:0x76a6a4,emissive:0x1e5655,emissiveIntensity:1.3})};
const world=new THREE.Group();scene.add(world);const box=(p,x,y,z,sx,sy,sz,mat,cast=true)=>{let o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;p.add(o);return o};const cyl=(p,x,y,z,r1,r2,h,mat,seg=8)=>{let o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;p.add(o);return o};
box(world,0,-.35,0,66,.7,66,mats.ground,false);for(let i=-30;i<=30;i+=6){box(world,i,-.005,0,.035,.01,60,mats.dirt,false);box(world,0,-.004,i,60,.01,.035,mats.dirt,false)}
// Ruined structures and forest ring
const obstacles=[];function wall(x,z,w,d,h=3){box(world,x,h/2,z,w,h,d,mats.stone);obstacles.push({x,z,r:Math.max(w,d)*.48})}
wall(-7,-8,13,.7,3.8);wall(0,-14,.7,12,3);wall(10,8,11,.8,3.5);wall(14,13,.8,8,3);wall(-15,11,8,.7,2.8);wall(-20,5,.7,10,3);wall(4,17,9,.7,3);wall(-4,7,.7,8,2.4);wall(21,-8,8,.7,3.4);wall(24,-3,.7,9,3);wall(-23,-13,9,.7,3.2);wall(-19,-18,.7,8,3);
