for(let i=0;i<110;i++){let a=Math.random()*Math.PI*2,r=23+Math.random()*12,x=Math.sin(a)*r,z=Math.cos(a)*r;let h=4+Math.random()*4;cyl(world,x,h/2,z,.22,.38,h,mats.bark,7);let crown=new THREE.Mesh(new THREE.IcosahedronGeometry(1.7+Math.random()*1.3,1),Math.random()>.5?mats.leaf:mats.leaf2);crown.position.set(x,h+1,z);crown.scale.set(1,1.2,1);crown.castShadow=true;world.add(crown)}
// scattered debris and lanterns
for(let i=0;i<36;i++){let x=(Math.random()-.5)*48,z=(Math.random()-.5)*48;if(Math.hypot(x,z)<5)continue;let o=box(world,x,.2,z,.3+Math.random(),.25,.25+Math.random(),i%3?mats.bark:mats.stone);o.rotation.y=Math.random()*3}
const gens=[],hooks=[],pallets=[],lockers=[],gates=[];
function makeGenerator(x,z,i){let g=new THREE.Group();g.position.set(x,0,z);world.add(g);box(g,0,.88,0,1.3,1.1,.72,mats.metal);box(g,0,1.53,0,.92,.3,.62,mats.rust);for(let k=0;k<3;k++){cyl(g,-.45+k*.45,.45,.39,.09,.09,.12,mats.glow,8).rotation.x=Math.PI/2}cyl(g,0,1.92,0,.13,.13,.55,mats.metal);let pipe=cyl(g,.47,1.28,0,.07,.07,.7,mats.metal);pipe.rotation.z=.4;let lamp=new THREE.PointLight(0xff6435,1.3,4);lamp.position.set(0,2.1,0);g.add(lamp);gens.push({x,z,group:g,progress:0,done:false,regress:0,phase:Math.random()*7,repairers:0,lamp})}
