function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');state.toastTimer=2.3}
function startMatch(){state.mode='match';state.started=performance.now();state.time=0;state.relays=0;state.gateActive=false;state.over=false;state.repair=0;state.skill=false;survivors.forEach((s,i)=>{s.hp='healthy';s.state='active';s.progress=0;s.escaped=false;s.group.position.set(-7+i*2,0,5+(i%2)*2);s.group.visible=true});killer.group.position.set(1,0,-1);killer.group.rotation.y=0;state.playerDown=false;
