function endMatch(win,title,copy){if(state.over)return;state.over=true;$('#end-title').innerHTML=title;$('#end-kicker').textContent=win?(state.role==='survivor'?'THE FOG RELEASES YOU':'THE GROUNDS ARE YOURS'):'THE HOLLOW CLAIMS ANOTHER';$('#end-copy').textContent=copy;$('#result-relays').textContent=`${state.relays} / 5`;$('#result-time').textContent=formatTime(state.time);$('#end-screen').classList.remove('hidden')}
function formatTime(n){let m=Math.floor(n/60),s=Math.floor(n%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function updateTeams(){let team=$('#team-list');team.innerHTML='';for(let i=0;i<4;i++){let s=survivors[i],row=document.createElement('div');row.className='teammate'+(s.hp==='downed'||s.hp==='captured'?' down':'');row.innerHTML=`<span class="avatar">${s.hp==='captured'?'⌁':s.hp==='downed'?'×':'◈'}</span><b>${s.name}</b><small>${s.hp==='captured'?'CAPTURED':s.hp==='downed'?'DOWN':s.escaped?'ESCAPED':i===0?'YOU':'ACTIVE'}</small>`;team.appendChild(row)}}
function nearestInteract(){let list=[];if(state.role==='survivor'&&player.hp==='healthy'||state.role==='survivor'&&player.hp==='injured'){
if(state.relays<5){for(let g of gens)if(!g.done)list.push({obj:g,type:'relay',d:dist(player.group.position,g.group.position),name:'RESTORE RELAY'})}
for(let s of survivors)if(s!==player&&(s.hp==='downed'||s.hp==='captured'))list.push({obj:s,type:s.hp==='downed'?'heal':'rescue',d:dist(player.group.position,s.group.position),name:s.hp==='downed'?'HELP SURVIVOR':'RESCUE SURVIVOR'});
for(let l of lockers)list.push({obj:l,type:'locker',d:dist(player.group.position,l.group.position),name:'HIDE IN LOCKER'});
if(state.gateActive)for(let g of gates)if(!g.open)list.push({obj:g,type:'gate',d:dist(player.group.position,g.group.position),name:'OPEN EXIT GATE'});
if(state.relays>=5&&state.relays<7)for(let g of gens)if(!g.done)list.push({obj:g,type:'bonus',d:dist(player.group.position,g.group.position),name:'RESTORE BONUS RELAY'});
}else if(state.role==='killer'){
for(let s of survivors)if(s.state==='active'&&!s.escaped)list.push({obj:s,type:s.hp==='downed'?'carry':'attack',d:dist(killer.group.position,s.group.position),name:s.hp==='downed'?'PICK UP SURVIVOR':'ATTACK SURVIVOR'});
if(killer.userData.carrying)for(let h of hooks)list.push({obj:h,type:'hook',d:dist(killer.group.position,h.group.position),name:'PLACE ON CAPTURE POST'});
for(let g of gens)if(!g.done)list.push({obj:g,type:'damage',d:dist(killer.group.position,g.group.position),name:'SABOTAGE RELAY'});
for(let p of pallets)if(!p.dropped)list.push({obj:p,type:'break',d:dist(killer.group.position,new THREE.Vector3(p.x,0,p.z)),name:'BREAK BARRICADE'});
for(let l of lockers)list.push({obj:l,type:'search',d:dist(killer.group.position,l.group.position),name:'SEARCH LOCKER'});
}
list.sort((a,b)=>a.d-b.d);return list[0]?.d<2.8?list[0]:null}
function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function applyInteraction(it){if(!it)return;let o=it.obj;if(it.type==='attack'){if(player===killer){o.hp=o.hp==='healthy'?'injured':'downed';o.group.rotation.x=o.hp==='downed'?Math.PI/2:0;killer.userData.cooldown=1.2;toast(o.name+(o.hp==='downed'?' is down':' is injured'));updateTeams();if(survivors.every(s=>s.hp==='downed'||s.hp==='captured'||s.escaped))endMatch(true,'NIGHT<br>CLAIMED','Every path through the Hollow belongs to you.')}}
if(it.type==='carry'&&player===killer){killer.userData.carrying=o;o.state='carried';o.group.visible=false;toast('Survivor captured. Find a post.')}if(it.type==='hook'&&player===killer&&killer.userData.carrying){let s=killer.userData.carrying;s.state='active';s.hp='captured';s.group.visible=true;s.group.position.set(o.x,0,o.z);s.hookTime=25;killer.userData.carrying=null;toast(s.name+' captured — rescue them!');updateTeams()}
if(it.type==='relay'||it.type==='bonus'){state.repairTarget=o;state.repair=0;state.interaction=it.type;$('#prompt-title').textContent=it.name;$('#prompt-sub').textContent='HOLD TO RESTORE';$('#center-prompt').classList.remove('hidden')}
if(it.type==='heal'||it.type==='rescue'){o.hp='injured';o.state='active';o.group.rotation.x=0;toast(it.type==='heal'?'Teammate recovered.':'Teammate rescued.');updateTeams()}
if(it.type==='gate'){state.repairTarget=o;state.repair=0;state.interaction='gate';$('#prompt-title').textContent='OPEN EXIT GATE';$('#prompt-sub').textContent='HOLD TO POWER THE SWITCH';$('#center-prompt').classList.remove('hidden')}
if(it.type==='damage'){o.regress=1.5;toast('Relay sabotaged. Progress is regressing.')}if(it.type==='break'){o.dropped=true;o.mesh.rotation.x=0;o.mesh.position.y=.35;toast('Barricade broken.')}if(it.type==='locker'){player.hidden=!player.hidden;player.group.visible=!player.hidden;toast(player.hidden?'Hidden. Stay quiet.':'You leave the locker.')}if(it.type==='search'){toast('The locker is empty.')} }
function completeRepair(){let t=state.repairTarget;if(!t)return;if(state.interaction==='relay'||state.interaction==='bonus'){t.progress=1;t.done=true;t.lamp.intensity=3;state.relays++;state.repairTarget=null;$('#center-prompt').classList.add('hidden');$('#objective-text').innerHTML=`${state.relays} <i>/ 5</i> RELAYS`;toast(state.relays>=5?'All relays online — find an exit!':'Relay restored. Keep going.');if(state.relays>=5){state.gateActive=true;beacon.intensity=18}if(state.relays>=7)state.relays=7}
if(state.interaction==='gate'){t.progress=1;t.open=true;state.repairTarget=null;$('#center-prompt').classList.add('hidden');toast('Exit open! Run!');if(state.role==='survivor'){player.escaped=true;endMatch(true,'NIGHT<br>ESCAPED','You found a way through the fog. The others may yet follow.')}}}

