 *{box-sizing:border-box} :root{--ink:#080b0c;--paper:#e8e5da;--red:#bd4939;--muted:#9a9b91;--line:rgba(225,222,210,.16);--display:'Barlow Condensed',Impact,sans-serif;--body:'DM Sans',sans-serif} html,body,#game-root{margin:0;width:100%;height:100%;overflow:hidden;background:#080b0c;color:var(--paper);font-family:var(--body)}body{user-select:none;-webkit-user-select:none;touch-action:none}button{font:inherit;color:inherit;cursor:pointer;border:0}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.grain,.vignette{position:absolute;inset:0;pointer-events:none}.grain{opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");mix-blend-mode:screen}.vignette{background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.4) 100%);z-index:1}.screen{position:absolute;inset:0;z-index:2;display:none;background:linear-gradient(90deg,rgba(5,8,9,.95) 0%,rgba(5,8,9,.82) 31%,rgba(5,8,9,.18) 68%,rgba(5,8,9,.15) 100%),linear-gradient(0deg,rgba(4,7,8,.7),transparent 30%)}.screen.visible{display:block}.topbar{position:absolute;top:0;left:0;right:0;height:86px;padding:24px 4.5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.07)}.brand-mark,.loader-mark{width:37px;height:37px;border:1px solid rgba(197,75,58,.65);display:grid;place-items:center;color:#d46752;font:700 15px var(--display);letter-spacing:-1px;transform:rotate(45deg)}.brand-mark{position:relative}.brand-mark:after{content:'AN';transform:rotate(-45deg)}.profile{display:flex;gap:14px;align-items:center;font-size:10px;letter-spacing:1.2px;color:#c5c6bd}.profile b{font-size:10px;color:#d75b45;border:1px solid rgba(215,91,69,.45);padding:5px 8px}.online-dot{width:6px;height:6