import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({channel:'chromium', headless:true, args:['--enable-gpu','--ignore-gpu-blocklist','--enable-unsafe-webgpu','--use-angle=vulkan','--enable-features=Vulkan','--use-vulkan=swiftshader','--use-webgpu-adapter=swiftshader','--disable-vulkan-surface']})
const page = await browser.newPage({viewport:{width:640,height:360}, deviceScaleFactor:1, isMobile:true, hasTouch:true})
const errors=[]
await page.route('**/game.js', async route => {
  const response=await route.fetch()
  const source=await response.text()
  const instrumentation = '\nwindow.__debug=function(){return {pos:player.group.position.toArray(),yaw,joy:{x:joy.x,y:joy.y},skill:state.skill,angle:state.skillAngle,repair:state.repair,target:state.repairTarget?.group.position.toArray()||null,relayProgress:state.repairTarget?.progress||0,relays:state.relays,toast:document.querySelector("#toast").textContent,teams:survivors.map(s=>({p:s.group.position.toArray(),hp:s.hp}))}};'
  await route.fulfill({response,body:source+instrumentation})
})
page.on('pageerror', e=>errors.push(e.message))
await page.goto('http://localhost:3002', {waitUntil:'load'})
await page.waitForTimeout(1400)
await page.locator('#play-button').click()
await page.waitForTimeout(300)
console.log('start', await page.evaluate(()=>window.__debug()))
const joy=await page.locator('#joystick').boundingBox()
await page.mouse.move(joy.x+joy.width/2,joy.y+joy.height/2)
await page.mouse.down()
await page.mouse.move(joy.x+joy.width/2+26,joy.y+joy.height/2-20,{steps:5})
await page.waitForTimeout(5500)
await page.mouse.up()
const after=await page.evaluate(()=>window.__debug())
console.log('natural approach',after)
const action=await page.locator('#touch-action').boundingBox()
await page.mouse.move(action.x+action.width/2,action.y+action.height/2)
await page.mouse.down()
await page.waitForTimeout(2500)
console.log('hold repair',await page.evaluate(()=>window.__debug()),'prompt',await page.locator('#center-prompt').getAttribute('class'),'skill',await page.locator('#skill-check').getAttribute('class'))
await page.mouse.up()
console.log('errors',errors)
await browser.close()

