33:function startMatch(){state.mode='match';state.started=performance.now();state.time=0;state.relays=0;state.gateActive=false;state.over=false;state.repair=0;state.skill=false;survivors.forEach((s,i)=>{s.hp='healthy';s.state='active';s.progress=0;s.escaped=false;s.group.position.set(-7+i*2,0,5+(i%2)*2);s.group.visible=true});killer.group.position.set(1,0,-1);killer.group.rotation.y=0;state.playerDown=false;state.escaped=0;state.repairTarget=null;state.interaction=null;state.repair=0;state.skill=false;state.skillPenalty=0;state.skillResume=0;state.mouseDown=false;state.run=false;state.crouch=false;joyAction=false;$('#center-prompt').classList.add('hidden');$('#skill-check').classList.add('hidden');gens.forEach(g=>{g.progress=0;g.done=false;g.regress=0;g.lamp.intensity=1.1});gates.forEach(g=>{g.progress=0;g.open=false});pallets.forEach(p=>{p.dropped=false;p.mesh.position.y=.56;p.mesh.rotation.x=0});survivors.forEach(s=>{s.userData={};s.hidden=false;s.state='active'});killer.userData={};killer.group.visible=true;beacon.intensity=10;
63:function checkSkill(){if(!state.skill)return;let a=((state.skillAngle%(Math.PI*2))+Math.PI*2)%(Math.PI*2),ok=a>5.0&&a<6.0;state.skill=false;$('#skill-check').classList.add('hidden');state.skillResume=1.25;if(ok){state.repair+=.12;toast('Perfect timing. Repair boosted.')}else{state.repairTarget.progress=Math.max(0,state.repairTarget.progress-.08);state.skillPenalty=1.5;toast('Missed — the Warden heard that!')}}
82:function updateMatch(dt){state.time=(performance.now()-state.started)/1000;if(state.skillResume>0)state.skillResume=Math.max(0,state.skillResume-dt);$('#clock').textContent=formatTime(state.time);if((killer.userData.cooldown||0)>0)killer.userData.cooldown-=dt;if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('#toast').classList.remove('show')}
85:if(state.repairTarget){let near=state.repairTarget.group?dist(player.group.position,state.repairTarget.group.position):99;if(near>3.1){stopInteraction()}else{let holding=state.mouseDown||keys.KeyE||joyAction;if(holding){let t=state.repairTarget;state.repair+=dt*(state.interaction==='gate'?.16:.11);let prog=Math.min(1,t.progress+dt*(state.interaction==='gate'?.04:.018));t.progress=prog;$('#prompt-progress').style.width=`${prog*100}%`;if(state.repair>=7&&!state.skill&&Math.random()<dt*.19){state.skill=true;state.skillAngle=0;$('#skill-check').classList.remove('hidden')}if(prog>=1)completeRepair()}if(state.repairTarget&&state.skill){state.skillAngle+=dt*3.4;$('#skill-needle').style.transform=`rotate(${state.skillAngle}rad)`}else if(state.repairTarget&&!holding&&state.skillResume<=0)stopInteraction()}}
89:let joyAction=false;function loop(now){requestAnimationFrame(loop);let dt=Math.min(.05,(now-(clock||now))/1000);clock=now;if(state.mode==='menu'){menuCamera.x=Math.sin(now*.0001)*2;camera.position.set(menuCamera.x,8+Math.sin(now*.00017)*.4,25);camera.lookAt(0,0,0);for(let g of gens){g.group.rotation.y=Math.sin(now*.0003+g.phase)*.05;g.lamp.intensity=1.1+Math.sin(now*.003+g.phase)*.5}}else if(state.mode==='match'&&!state.paused&&!state.over){updateMatch(dt);for(let g of gens){g.group.rotation.y=Math.sin(now*.001+g.phase)*.02;g.lamp.intensity=g.done?3:1.1+Math.sin(now*.003+g.phase)*.35}}renderer.render(scene,camera)}requestAnimationFrame(loop);
95:const joyEl=$('#joystick'),knob=$('.joystick-knob');let joyPointer=null;joyEl.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joyEl.setPointerCapture(e.pointerId);joyMove(e)});joyEl.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e)});function joyMove(e){let r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=33;if(len>max){dx*=max/len;dy*=max/len}joy.x=dx/max;joy.y=dy/max;knob.style.transform=`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px))`}function resetJoy(){joyPointer=null;joy.x=0;joy.y=0;knob.style.transform='translate(-50%,-50%)'}joyEl.addEventListener('pointerup',resetJoy);joyEl.addEventListener('pointercancel',resetJoy);
97:$('#touch-sprint').addEventListener('pointerdown',e=>{e.stopPropagation();state.run=true});$('#touch-sprint').addEventListener('pointerup',()=>{state.run=false});$('#touch-sprint').addEventListener('pointercancel',()=>{state.run=false});$('#touch-action').addEventListener('pointerdown',e=>{e.stopPropagation();joyAction=true;if(state.skill)checkSkill();else if(!state.repairTarget)startInteraction()});$('#touch-action').addEventListener('pointerup',()=>{joyAction=false});$('#touch-action').addEventListener('pointercancel',()=>{joyAction=false});$('#skill-check').addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();if(state.skill)checkSkill()});$('#touch-ability').addEventListener('click',()=>{if(state.role==='killer'){toast('Scent trail revealed — follow the red sparks.');killer.userData.power=3}});

